FUNCTION_BLOCK FB_Semiconductor_MagnetronSputter_ArcSuppress
(*
 =========================================================================================
  LUMINA ADVANCED SEMICONDUCTOR PVD SYSTEMS DIVISION - INDUSTRIAL CONTROL SYSTEMS
  300mm WAFER FABRICATION - DUAL-CATHODE AC MAGNETRON SPUTTER DEPOSITION SYSTEM
  ARC SUPPRESSION, TMR 2oo3 FAST MONITORING & SUBSTRATE BIAS IMPEDANCE MATCHING (MPC)
 =========================================================================================
  Author   : Lumina V7 Principal Automation Fellow & Cyber-Physical Systems Chair
  Standard : IEC 61131-3 3rd Edition (Deterministic Industrial Automation ST)
  Target   : Dual-Cathode 40 kHz AC Reactive PVD (Al2O3 / TiN Dielectric & Barrier Metallization)
  Safety   : SIL-3 / Cat 4 Architecture with 2oo3 Sensor Voting & Graceful Degradation
 =========================================================================================
*)
VAR_INPUT
    bSystemEnable                   : BOOL;     (* [binary] Master host run command from cluster tool supervisory controller *)
    bEStopOk                        : BOOL;     (* [binary] Safety relay dual-channel string healthy (active TRUE) *)
    bChamberVacuumInterlock         : BOOL;     (* [binary] High-vacuum slit & gate valve isolation interlock satisfied *)
    rCathodePowerSet_kW             : REAL;     (* [kW] Dual-cathode AC 40kHz active power setpoint (0.0 to 120.0 kW) *)
    rCathodeFrequencySet_kHz        : REAL;     (* [kHz] Dual-cathode AC switching frequency setpoint (20.0 to 100.0 kHz) *)
    rArgonFlow_sccm                 : REAL;     (* [sccm] Mass Flow Controller 1 (Ar) process gas flow (0.0 to 500.0 sccm) *)
    rReactiveGasFlow_sccm           : REAL;     (* [sccm] Mass Flow Controller 2 (O2/N2) reactive gas flow (0.0 to 250.0 sccm) *)
    rChamberPressure_mbar           : REAL;     (* [mbar] High-precision capacitance diaphragm gauge (1.0E-4 to 1.0E-1 mbar) *)
    rCathodeVoltSense_ChA_V         : REAL;     (* [V] Cathode voltage fast isolated analog sensor ChA (-1200.0 to +1200.0 V) *)
    rCathodeVoltSense_ChB_V         : REAL;     (* [V] Cathode voltage fast isolated analog sensor ChB (-1200.0 to +1200.0 V) *)
    rCathodeVoltSense_ChC_V         : REAL;     (* [V] Cathode voltage fast isolated analog sensor ChC (-1200.0 to +1200.0 V) *)
    rCathodeCurrSense_ChA_A         : REAL;     (* [A] Cathode current high-bandwidth Rogowski coil ChA (0.0 to 400.0 A) *)
    rCathodeCurrSense_ChB_A         : REAL;     (* [A] Cathode current high-bandwidth Rogowski coil ChB (0.0 to 400.0 A) *)
    rCathodeCurrSense_ChC_A         : REAL;     (* [A] Cathode current high-bandwidth Rogowski coil ChC (0.0 to 400.0 A) *)
    rSubstrateBiasFwdPower_kW       : REAL;     (* [kW] 13.56 MHz RF substrate bias generator forward power (0.0 to 15.0 kW) *)
    rSubstrateBiasReflPower_kW      : REAL;     (* [kW] 13.56 MHz RF substrate bias generator reflected power (0.0 to 5.0 kW) *)
    rRfPhaseError_V                 : REAL;     (* [V] RF phase detector error voltage (-10.0 to +10.0 V, 0.0V = 50 Ohm pure R) *)
    rRfMagnitudeError_V             : REAL;     (* [V] RF magnitude detector error voltage (-10.0 to +10.0 V, 0.0V = matched |Z|) *)
    rCoolantFlowRate_Lmin           : REAL;     (* [L/min] Cathode magnetron target DI water coolant flow (Nominal >= 45.0 L/min) *)
    rCoolantDeltaTemp_degC          : REAL;     (* [deg C] Coolant temperature rise (T_out - T_in) (Max trip limit 12.0 deg C) *)
    bResetFault                     : BOOL;     (* [binary] Master operator fault acknowledgment and alarm reset pulse *)
END_VAR

VAR_OUTPUT
    bPlasmaActive                   : BOOL;     (* [binary] Stable dual-cathode AC plasma discharge sustained *)
    bArcSuppressionActive           : BOOL;     (* [binary] Active reverse-voltage pulse arc quench circuit energized *)
    bMatchingNetworkLocked          : BOOL;     (* [binary] Substrate RF bias auto-match network converged (VSWR <= 1.05:1) *)
    bSystemHealthy                  : BOOL;     (* [binary] Chamber PVD cell operational integrity status (all loops healthy) *)
    bDegradedSensorMode             : BOOL;     (* [binary] TMR 2oo3 sensor fallback to 1oo2 due to single transducer mismatch *)
    rCathodePowerActual_kW          : REAL;     (* [kW] Filtered true active AC power delivered to dual sputtering targets *)
    rCathodeVoltageVoted_V          : REAL;     (* [V] 2oo3 TMR median-voted instantaneous cathode voltage *)
    rCathodeCurrentVoted_A          : REAL;     (* [A] 2oo3 TMR median-voted instantaneous cathode current *)
    rArcRate_Hz                     : REAL;     (* [Hz] Real-time sliding-window micro-arc occurrence frequency *)
    rCumulativeArcEnergy_J          : REAL;     (* [J] Integrated thermal arc dissipation energy across current wafer run *)
    rTuneCapacitorPos_pct           : REAL;     (* [%] Substrate matchbox series tune capacitor command (0.0 to 100.0 %) *)
    rLoadCapacitorPos_pct           : REAL;     (* [%] Substrate matchbox shunt load capacitor command (0.0 to 100.0 %) *)
    rVSWR                           : REAL;     (* [ratio] Voltage Standing Wave Ratio on 13.56 MHz substrate bias line *)
    rEstimatedSheathCap_pF          : REAL;     (* [pF] Discrete observer state: Dynamic wafer plasma sheath capacitance *)
    rEstimatedBulkResistance_Ohm    : REAL;     (* [Ohm] Discrete observer state: Bulk plasma electrical resistance *)
    dwStatusWord                    : DWORD;    (* [bitmask] 32-bit PVD subsystem operational status bit register *)
    dwAlarmWord                     : DWORD;    (* [bitmask] 32-bit PVD subsystem diagnostic & critical trip alarm bit register *)
END_VAR

VAR
    (* --- State Machine & Timers --- *)
    iState                          : INT := 0; (* Primary Process Sequencer State *)
    tStateTimer                     : TON;      (* State dwelling duration timer *)
    tArcQuenchTimer                 : TON;      (* Microsecond-grade arc quench duration pulse timer *)
    tDiscrepancyTimer_V             : TON;      (* Voltage sensor discrepancy tolerance qualification timer *)
    tDiscrepancyTimer_I             : TON;      (* Current sensor discrepancy tolerance qualification timer *)
    tMpcCycleTimer                  : TON;      (* Discrete Model Predictive Control 10ms execution scheduler *)
    tArcWindowTimer                 : TON;      (* 1.0-second sliding window integration timer for arc frequency *)

    (* --- TMR 2oo3 Voting & Fault Isolation Variables --- *)
    bVoltChA_Valid                  : BOOL := TRUE;
    bVoltChB_Valid                  : BOOL := TRUE;
    bVoltChC_Valid                  : BOOL := TRUE;
    bCurrChA_Valid                  : BOOL := TRUE;
    bCurrChB_Valid                  : BOOL := TRUE;
    bCurrChC_Valid                  : BOOL := TRUE;
    rDelta_V_AB                     : REAL;
    rDelta_V_BC                     : REAL;
    rDelta_V_CA                     : REAL;
    rDelta_I_AB                     : REAL;
    rDelta_I_BC                     : REAL;
    rDelta_I_CA                     : REAL;

    (* --- High-Speed Arc Discrimination Variables --- *)
    rCathodeVolt_Prev               : REAL := 0.0;
    rCathodeCurr_Prev               : REAL := 0.0;
    rdV_dt                          : REAL := 0.0; (* Cathode voltage derivative [V/s] *)
    rdI_dt                          : REAL := 0.0; (* Cathode current derivative [A/s] *)
    bMicroArcDetected               : BOOL := FALSE;
    bHardArcDetected                : BOOL := FALSE;
    iHardArcConsecutiveCount        : INT := 0;
    iArcCounterInWindow             : INT := 0;
    arArcTimestamps                 : ARRAY[0..63] OF TIME;
    iArcRingIdx                     : INT := 0;
    rCycleTime_s                    : REAL := 0.001; (* 1.0 ms nominal deterministic PLC scan interval *)

    (* --- Substrate RF Bias Model Predictive Control (MPC) & State-Space Observer --- *)
    (* Dynamic System Representation:
       x_{k+1} = A_mpc * x_k + B_mpc * u_k + L_obs * (y_k - C_mpc * x_k)
       y_k     = C_mpc * x_k + D_mpc * u_k
       States x: [1] = Delta Sheath Capacitance (pF), [2] = Delta Bulk Plasma Resistance (Ohm)
       Inputs u: [1] = Tune Capacitor Slew Rate (%/s), [2] = Load Capacitor Slew Rate (%/s)
       Outputs y: [1] = RF Phase Error (V), [2] = RF Magnitude Error (V)
    *)
    x_hat                           : ARRAY[1..2] OF REAL := [0.0, 0.0]; (* Observer estimated state vector *)
    u_mpc                           : ARRAY[1..2] OF REAL := [0.0, 0.0]; (* Calculated optimal control vector *)
    y_meas                          : ARRAY[1..2] OF REAL := [0.0, 0.0]; (* Measured output error vector *)
    y_pred                          : ARRAY[1..2] OF REAL := [0.0, 0.0]; (* Predicted model output vector *)

    (* Discrete State Transition Matrix A (2x2) at dt = 10ms *)
    A_mpc_11                        : REAL := 0.9120;
    A_mpc_12                        : REAL := 0.0480;
    A_mpc_21                        : REAL := -0.0350;
    A_mpc_22                        : REAL := 0.8850;

    (* Input Coupling Matrix B (2x2) *)
    B_mpc_11                        : REAL := 0.2850;
    B_mpc_12                        : REAL := 0.0520;
    B_mpc_21                        : REAL := 0.0380;
    B_mpc_22                        : REAL := 0.2410;

    (* Output Observation Matrix C (2x2) *)
    C_mpc_11                        : REAL := 1.0000;
    C_mpc_12                        : REAL := 0.0000;
    C_mpc_21                        : REAL := 0.0000;
    C_mpc_22                        : REAL := 1.0000;

    (* Luenberger / Steady-State Kalman Observer Gain Matrix L (2x2) *)
    L_obs_11                        : REAL := 0.3800;
    L_obs_12                        : REAL := 0.0150;
    L_obs_21                        : REAL := 0.0120;
    L_obs_22                        : REAL := 0.3400;

    (* MPC Optimal Feedback Matrix K_mpc derived via Riccati equation (2x2) *)
    K_mpc_11                        : REAL := 1.4500;
    K_mpc_12                        : REAL := 0.1800;
    K_mpc_21                        : REAL := 0.1200;
    K_mpc_22                        : REAL := 1.3200;

    (* Physical Capacitor Actuator Positioning *)
    rTuneCapInternal_pct            : REAL := 50.0;
    rLoadCapInternal_pct            : REAL := 50.0;
    rMaxCapVelocity_pct_s           : REAL := 20.0; (* Slew rate saturation limit *)

    (* --- Filter Accumulators and Constants --- *)
    rCathodePowerFilt_kW            : REAL := 0.0;
    rPowerFilterAlpha               : REAL := 0.08; (* First-order low pass filter coefficient *)
    rGammaMag                       : REAL := 0.0;  (* RF reflection coefficient magnitude *)
    iIgnitionAttemptCount           : INT := 0;
    rPowerRampTarget_kW             : REAL := 0.0;
    rPowerRampCurrent_kW            : REAL := 0.0;
    rPowerRampRate_kW_s             : REAL := 15.0; (* 15 kW/s ramp gradient *)
END_VAR

(* ========================================================================================= *)
(* CRITICAL SAFETY INTERLOCKS & EMERGENCY SHUTDOWN                                           *)
(* ========================================================================================= *)
IF NOT bEStopOk THEN
    (* Unconditional immediate hardware safety trip *)
    iState := 99; (* LOCKOUT_EMERGENCY_SHUTDOWN *)
    bPlasmaActive := FALSE;
    bArcSuppressionActive := FALSE;
    bMatchingNetworkLocked := FALSE;
    bSystemHealthy := FALSE;
    rCathodePowerActual_kW := 0.0;
    rCathodeVoltageVoted_V := 0.0;
    rCathodeCurrentVoted_A := 0.0;
    dwAlarmWord := dwAlarmWord OR 16#00000001; (* Bit 0: Hardware E-Stop Open *)
    dwStatusWord := 16#80000000;              (* Bit 31: Emergency Lockout *)
    RETURN;
END_IF;

(* Diagnostic Fault Acknowledge Handler *)
IF bResetFault THEN
    dwAlarmWord := 16#00000000;
    iHardArcConsecutiveCount := 0;
    iIgnitionAttemptCount := 0;
    rCumulativeArcEnergy_J := 0.0;
    IF iState = 99 AND bChamberVacuumInterlock THEN
        iState := 0; (* Return to IDLE_STANDBY *)
    END_IF;
END_IF;

(* ========================================================================================= *)
(* 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) VOTING & SENSOR VALIDATION                          *)
(* ========================================================================================= *)
(* Evaluate Cathode Voltage Sensor Triad Cross-Discrepancies *)
rDelta_V_AB := ABS(rCathodeVoltSense_ChA_V - rCathodeVoltSense_ChB_V);
rDelta_V_BC := ABS(rCathodeVoltSense_ChB_V - rCathodeVoltSense_ChC_V);
rDelta_V_CA := ABS(rCathodeVoltSense_ChC_V - rCathodeVoltSense_ChA_V);

(* Tolerance threshold: 65.0 V deviation qualifies single-sensor anomaly *)
bVoltChA_Valid := NOT (rDelta_V_AB > 65.0 AND rDelta_V_CA > 65.0);
bVoltChB_Valid := NOT (rDelta_V_AB > 65.0 AND rDelta_V_BC > 65.0);
bVoltChC_Valid := NOT (rDelta_V_BC > 65.0 AND rDelta_V_CA > 65.0);

(* 2oo3 Voltage Median Selection Algorithm *)
IF bVoltChA_Valid AND bVoltChB_Valid AND bVoltChC_Valid THEN
    (* All channels healthy: classical median selection *)
    IF (rCathodeVoltSense_ChA_V >= rCathodeVoltSense_ChB_V AND rCathodeVoltSense_ChA_V <= rCathodeVoltSense_ChC_V) OR
       (rCathodeVoltSense_ChA_V <= rCathodeVoltSense_ChB_V AND rCathodeVoltSense_ChA_V >= rCathodeVoltSense_ChC_V) THEN
        rCathodeVoltageVoted_V := rCathodeVoltSense_ChA_V;
    ELSIF (rCathodeVoltSense_ChB_V >= rCathodeVoltSense_ChA_V AND rCathodeVoltSense_ChB_V <= rCathodeVoltSense_ChC_V) OR
          (rCathodeVoltSense_ChB_V <= rCathodeVoltSense_ChA_V AND rCathodeVoltSense_ChB_V >= rCathodeVoltSense_ChC_V) THEN
        rCathodeVoltageVoted_V := rCathodeVoltSense_ChB_V;
    ELSE
        rCathodeVoltageVoted_V := rCathodeVoltSense_ChC_V;
    END_IF;
    bDegradedSensorMode := FALSE;
ELSIF bVoltChA_Valid AND bVoltChB_Valid THEN
    (* Channel C failed: Degraded 1oo2 average between A and B *)
    rCathodeVoltageVoted_V := (rCathodeVoltSense_ChA_V + rCathodeVoltSense_ChB_V) * 0.5;
    bDegradedSensorMode := TRUE;
    dwAlarmWord := dwAlarmWord OR 16#00000040; (* Bit 6: Voltage Sensor TMR Anomaly *)
ELSIF bVoltChB_Valid AND bVoltChC_Valid THEN
    (* Channel A failed: Degraded 1oo2 average between B and C *)
    rCathodeVoltageVoted_V := (rCathodeVoltSense_ChB_V + rCathodeVoltSense_ChC_V) * 0.5;
    bDegradedSensorMode := TRUE;
    dwAlarmWord := dwAlarmWord OR 16#00000040;
ELSIF bVoltChA_Valid AND bVoltChC_Valid THEN
    (* Channel B failed: Degraded 1oo2 average between A and C *)
    rCathodeVoltageVoted_V := (rCathodeVoltSense_ChA_V + rCathodeVoltSense_ChC_V) * 0.5;
    bDegradedSensorMode := TRUE;
    dwAlarmWord := dwAlarmWord OR 16#00000040;
ELSE
    (* Multiple sensor failure: Complete loss of voting integrity *)
    dwAlarmWord := dwAlarmWord OR 16#00000080; (* Bit 7: Critical Dual Sensor Loss *)
    iState := 80; (* Trigger Controlled Graceful Rampdown *)
END_IF;

(* Evaluate Cathode Current Rogowski Coil Triad Discrepancies *)
rDelta_I_AB := ABS(rCathodeCurrSense_ChA_A - rCathodeCurrSense_ChB_A);
rDelta_I_BC := ABS(rCathodeCurrSense_ChB_A - rCathodeCurrSense_ChC_A);
rDelta_I_CA := ABS(rCathodeCurrSense_ChC_A - rCathodeCurrSense_ChA_A);

(* Tolerance threshold: 25.0 A deviation qualifies current transducer fault *)
bCurrChA_Valid := NOT (rDelta_I_AB > 25.0 AND rDelta_I_CA > 25.0);
bCurrChB_Valid := NOT (rDelta_I_AB > 25.0 AND rDelta_I_BC > 25.0);
bCurrChC_Valid := NOT (rDelta_I_BC > 25.0 AND rDelta_I_CA > 25.0);

(* 2oo3 Current Median Selection Algorithm *)
IF bCurrChA_Valid AND bCurrChB_Valid AND bCurrChC_Valid THEN
    IF (rCathodeCurrSense_ChA_A >= rCathodeCurrSense_ChB_A AND rCathodeCurrSense_ChA_A <= rCathodeCurrSense_ChC_A) OR
       (rCathodeCurrSense_ChA_A <= rCathodeCurrSense_ChB_A AND rCathodeCurrSense_ChA_A >= rCathodeCurrSense_ChC_A) THEN
        rCathodeCurrentVoted_A := rCathodeCurrSense_ChA_A;
    ELSIF (rCathodeCurrSense_ChB_A >= rCathodeCurrSense_ChA_A AND rCathodeCurrSense_ChB_A <= rCathodeCurrSense_ChC_A) OR
          (rCathodeCurrSense_ChB_A <= rCathodeCurrSense_ChA_A AND rCathodeCurrSense_ChB_A >= rCathodeCurrSense_ChC_A) THEN
        rCathodeCurrentVoted_A := rCathodeCurrSense_ChB_A;
    ELSE
        rCathodeCurrentVoted_A := rCathodeCurrSense_ChC_A;
    END_IF;
ELSIF bCurrChA_Valid AND bCurrChB_Valid THEN
    rCathodeCurrentVoted_A := (rCathodeCurrSense_ChA_A + rCathodeCurrSense_ChB_A) * 0.5;
    bDegradedSensorMode := TRUE;
    dwAlarmWord := dwAlarmWord OR 16#00000100; (* Bit 8: Current Sensor TMR Anomaly *)
ELSIF bCurrChB_Valid AND bCurrChC_Valid THEN
    rCathodeCurrentVoted_A := (rCathodeCurrSense_ChB_A + rCathodeCurrSense_ChC_A) * 0.5;
    bDegradedSensorMode := TRUE;
    dwAlarmWord := dwAlarmWord OR 16#00000100;
ELSIF bCurrChA_Valid AND bCurrChC_Valid THEN
    rCathodeCurrentVoted_A := (rCathodeCurrSense_ChA_A + rCathodeCurrSense_ChC_A) * 0.5;
    bDegradedSensorMode := TRUE;
    dwAlarmWord := dwAlarmWord OR 16#00000100;
ELSE
    dwAlarmWord := dwAlarmWord OR 16#00000200; (* Bit 9: Critical Dual Current Sensor Loss *)
    iState := 80; (* Trigger Controlled Graceful Rampdown *)
END_IF;

(* Filtered True Active Cathode Power Calculation *)
rCathodePowerFilt_kW := (1.0 - rPowerFilterAlpha) * rCathodePowerFilt_kW +
                        rPowerFilterAlpha * (ABS(rCathodeVoltageVoted_V) * rCathodeCurrentVoted_A / 1000.0);
rCathodePowerActual_kW := rCathodePowerFilt_kW;

(* ========================================================================================= *)
(* ULTRA-FAST ARC DETECTION & DISCRIMINATION LOGIC                                          *)
(* ========================================================================================= *)
(* Calculate discrete temporal derivatives with cycle-time normalization *)
IF rCycleTime_s > 0.0001 THEN
    rdV_dt := (rCathodeVoltageVoted_V - rCathodeVolt_Prev) / rCycleTime_s;
    rdI_dt := (rCathodeCurrentVoted_A - rCathodeCurr_Prev) / rCycleTime_s;
END_IF;
rCathodeVolt_Prev := rCathodeVoltageVoted_V;
rCathodeCurr_Prev := rCathodeCurrentVoted_A;

(* Micro-Arc Condition: Rapid voltage collapse (dV/dt < -400 kV/s) accompanied by moderate current rise *)
bMicroArcDetected := (rdV_dt < -400000.0) AND (rdI_dt > 15000.0) AND (ABS(rCathodeVoltageVoted_V) < 220.0);

(* Hard-Arc Condition: Sustained low voltage (< 95V) combined with extreme surge current (> 180A) *)
bHardArcDetected := (ABS(rCathodeVoltageVoted_V) < 95.0) AND (rCathodeCurrentVoted_A > 180.0);

(* Real-Time Arc Energy Integration: E = Integral(V * I * dt) *)
IF bMicroArcDetected OR bHardArcDetected OR bArcSuppressionActive THEN
    rCumulativeArcEnergy_J := rCumulativeArcEnergy_J +
                              (ABS(rCathodeVoltageVoted_V) * rCathodeCurrentVoted_A * rCycleTime_s);
END_IF;

(* 1.0-Second Sliding Window Arc Rate Calculator *)
tArcWindowTimer(IN := NOT tArcWindowTimer.Q, PT := T#1S);
IF tArcWindowTimer.Q THEN
    rArcRate_Hz := INT_TO_REAL(iArcCounterInWindow);
    iArcCounterInWindow := 0;
END_IF;

IF bMicroArcDetected OR bHardArcDetected THEN
    iArcCounterInWindow := iArcCounterInWindow + 1;
END_IF;

(* Arc Rate Runaway Protection *)
IF rArcRate_Hz > 120.0 THEN
    dwAlarmWord := dwAlarmWord OR 16#00000400; (* Bit 10: Arc Rate Frequency Exceeded *)
    iState := 80; (* Controlled Power Rampdown *)
END_IF;

(* ========================================================================================= *)
(* 13.56 MHz SUBSTRATE BIAS IMPEDANCE MATCHING MODEL PREDICTIVE CONTROL (MPC)                *)
(* ========================================================================================= *)
(* Calculate Voltage Standing Wave Ratio (VSWR) *)
IF rSubstrateBiasFwdPower_kW > 0.05 THEN
    rGammaMag := SQRT(LIMIT(0.0, rSubstrateBiasReflPower_kW / rSubstrateBiasFwdPower_kW, 0.999));
    rVSWR := (1.0 + rGammaMag) / LIMIT(0.01, (1.0 - rGammaMag), 1.0);
ELSE
    rVSWR := 1.0;
END_IF;

bMatchingNetworkLocked := (rVSWR <= 1.05) AND (rSubstrateBiasFwdPower_kW > 0.1);

(* Discrete MPC & Observer Execution Loop (Runs every 10ms deterministic slice) *)
tMpcCycleTimer(IN := NOT tMpcCycleTimer.Q, PT := T#10MS);
IF tMpcCycleTimer.Q THEN
    (* Form measured error vector from matchbox RF sensor pickoffs *)
    y_meas[1] := rRfPhaseError_V;
    y_meas[2] := rRfMagnitudeError_V;

    (* Model Output Prediction: y_pred = C * x_hat *)
    y_pred[1] := C_mpc_11 * x_hat[1] + C_mpc_12 * x_hat[2];
    y_pred[2] := C_mpc_21 * x_hat[1] + C_mpc_22 * x_hat[2];

    (* Luenberger State-Space Observer Update:
       x_hat = A * x_hat + B * u + L * (y_meas - y_pred) *)
    x_hat[1] := (A_mpc_11 * x_hat[1] + A_mpc_12 * x_hat[2]) +
                (B_mpc_11 * u_mpc[1] + B_mpc_12 * u_mpc[2]) +
                (L_obs_11 * (y_meas[1] - y_pred[1]) + L_obs_12 * (y_meas[2] - y_pred[2]));

    x_hat[2] := (A_mpc_21 * x_hat[1] + A_mpc_22 * x_hat[2]) +
                (B_mpc_21 * u_mpc[1] + B_mpc_22 * u_mpc[2]) +
                (L_obs_21 * (y_meas[1] - y_pred[1]) + L_obs_22 * (y_meas[2] - y_pred[2]));

    (* Extract Observable Physical Parameters *)
    rEstimatedSheathCap_pF       := 350.0 + x_hat[1] * 25.0;  (* Baseline sheath cap + delta *)
    rEstimatedBulkResistance_Ohm := 12.5 + x_hat[2] * 4.2;    (* Baseline bulk resistance + delta *)

    (* Compute Optimal Control Action via State-Feedback: u = -K * x_hat *)
    IF bPlasmaActive AND (rSubstrateBiasFwdPower_kW > 0.05) THEN
        u_mpc[1] := -(K_mpc_11 * x_hat[1] + K_mpc_12 * x_hat[2]);
        u_mpc[2] := -(K_mpc_21 * x_hat[1] + K_mpc_22 * x_hat[2]);

        (* Slew rate saturation limiting *)
        u_mpc[1] := LIMIT(-rMaxCapVelocity_pct_s, u_mpc[1], rMaxCapVelocity_pct_s);
        u_mpc[2] := LIMIT(-rMaxCapVelocity_pct_s, u_mpc[2], rMaxCapVelocity_pct_s);

        (* Numerical integration to motor position commands (dt = 0.010 s) *)
        rTuneCapInternal_pct := LIMIT(0.0, rTuneCapInternal_pct + u_mpc[1] * 0.010, 100.0);
        rLoadCapInternal_pct := LIMIT(0.0, rLoadCapInternal_pct + u_mpc[2] * 0.010, 100.0);
    ELSE
        u_mpc[1] := 0.0;
        u_mpc[2] := 0.0;
    END_IF;

    rTuneCapacitorPos_pct := rTuneCapInternal_pct;
    rLoadCapacitorPos_pct := rLoadCapInternal_pct;
END_IF;

(* Matchbox Reflected Power Excursion Protection *)
IF (rSubstrateBiasReflPower_kW > 2.8) OR (rVSWR > 3.2 AND rSubstrateBiasFwdPower_kW > 1.0) THEN
    dwAlarmWord := dwAlarmWord OR 16#00000800; (* Bit 11: Matchbox Severe Misalignment *)
END_IF;

(* ========================================================================================= *)
(* MAIN PROCESS FINITE STATE MACHINE (FSM)                                                  *)
(* ========================================================================================= *)
CASE iState OF
    0: (* --- STATE 0: IDLE / STANDBY --- *)
        bPlasmaActive := FALSE;
        bArcSuppressionActive := FALSE;
        rPowerRampCurrent_kW := 0.0;
        iHardArcConsecutiveCount := 0;
        dwStatusWord := 16#00000001; (* Status: Standby Ready *)

        IF bSystemEnable AND bChamberVacuumInterlock THEN
            tStateTimer(IN := FALSE);
            iState := 10; (* Transition to Pre-Flight Interlock Verification *)
        END_IF;

    10: (* --- STATE 10: PRE-FLIGHT INTERLOCK & VACUUM VERIFICATION --- *)
        dwStatusWord := 16#00000002; (* Status: Interlock Check *)

        (* Verify High-Vacuum Base Pressure and Cooling Water Integrity *)
        IF (rChamberPressure_mbar < 1.0E-4) OR (rChamberPressure_mbar > 6.0E-2) THEN
            dwAlarmWord := dwAlarmWord OR 16#00000002; (* Bit 1: Chamber Pressure Out of Range *)
        END_IF;

        IF rCoolantFlowRate_Lmin < 42.0 THEN
            dwAlarmWord := dwAlarmWord OR 16#00000004; (* Bit 2: Cathode Coolant Flow Depleted *)
        END_IF;

        IF rCoolantDeltaTemp_degC > 11.5 THEN
            dwAlarmWord := dwAlarmWord OR 16#00000008; (* Bit 3: Cathode Coolant Over-Temperature *)
        END_IF;

        IF (dwAlarmWord = 0) THEN
            iState := 20; (* Transition to Working Gas Stabilization *)
        ELSE
            iState := 99; (* Abort to Lockout on Pre-flight Failure *)
        END_IF;

    20: (* --- STATE 20: WORKING GAS & PRESSURE STABILIZATION --- *)
        dwStatusWord := 16#00000004; (* Status: Gas Purge & Pressure Balance *)
        tStateTimer(IN := TRUE, PT := T#3S);

        (* Confirm Argon flow and chamber pressure within reactive deposition window *)
        IF (rArgonFlow_sccm > 40.0) AND (rChamberPressure_mbar >= 2.0E-3) AND (rChamberPressure_mbar <= 9.0E-3) THEN
            IF tStateTimer.Q THEN
                tStateTimer(IN := FALSE);
                iState := 30; (* Ready for Plasma Ignition *)
            END_IF;
        END_IF;

        IF NOT bSystemEnable THEN
            iState := 80; (* Abort to Rampdown *)
        END_IF;

    30: (* --- STATE 30: PRE-IGNITION HIGH VOLTAGE STRIKE --- *)
        dwStatusWord := 16#00000008; (* Status: Plasma Strike Ignition *)
        tStateTimer(IN := TRUE, PT := T#2S);

        (* Ignition Detection Criteria: Current conduction (> 8.0A) and voltage breakdown *)
        IF (rCathodeCurrentVoted_A > 8.0) AND (ABS(rCathodeVoltageVoted_V) > 280.0) THEN
            bPlasmaActive := TRUE;
            iIgnitionAttemptCount := 0;
            tStateTimer(IN := FALSE);
            iState := 40; (* Transition to Power Ramp *)
        ELSIF tStateTimer.Q THEN
            (* Ignition Strike Timeout Encountered *)
            iIgnitionAttemptCount := iIgnitionAttemptCount + 1;
            tStateTimer(IN := FALSE);
            IF iIgnitionAttemptCount >= 3 THEN
                dwAlarmWord := dwAlarmWord OR 16#00000010; (* Bit 4: Three Strike Failures *)
                iState := 99;
            ELSE
                iState := 20; (* Re-purge and re-attempt *)
            END_IF;
        END_IF;

    40: (* --- STATE 40: DUAL-CATHODE POWER RAMP-UP --- *)
        dwStatusWord := 16#00000010; (* Status: Active Power Ramp *)

        (* Ramp power at defined rate until setpoint reached *)
        IF rPowerRampCurrent_kW < rCathodePowerSet_kW THEN
            rPowerRampCurrent_kW := rPowerRampCurrent_kW + (rPowerRampRate_kW_s * rCycleTime_s);
            IF rPowerRampCurrent_kW >= rCathodePowerSet_kW THEN
                rPowerRampCurrent_kW := rCathodePowerSet_kW;
                iState := 50; (* Enter Steady-State Sputter Deposition *)
            END_IF;
        ELSE
            rPowerRampCurrent_kW := rCathodePowerSet_kW;
            iState := 50;
        END_IF;

        (* Intercept micro-arcs during ramp *)
        IF bMicroArcDetected THEN
            iState := 60;
        END_IF;

    50: (* --- STATE 50: STEADY-STATE DUAL-CATHODE AC SPUTTERING --- *)
        dwStatusWord := 16#00000020; (* Status: Steady-State Deposition Process *)
        bPlasmaActive := TRUE;
        bSystemHealthy := (dwAlarmWord = 0);

        (* Continuous Reactive Process Interlocks *)
        IF (rReactiveGasFlow_sccm > 0.0) AND (rArgonFlow_sccm < 30.0) THEN
            dwAlarmWord := dwAlarmWord OR 16#00000020; (* Bit 5: Target Poisoning Stoichiometry Hazard *)
        END_IF;

        (* Micro-Arc Trigger: Divert to fast asymmetric reverse-pulse quench *)
        IF bMicroArcDetected THEN
            iState := 60;
        END_IF;

        (* Hard-Arc Trigger: Direct high-energy arc trip *)
        IF bHardArcDetected THEN
            iState := 70;
        END_IF;

        (* Normal Recipe Run Termination *)
        IF NOT bSystemEnable THEN
            iState := 80;
        END_IF;

    60: (* --- STATE 60: MICRO-ARC REVERSE-PULSE ACTIVE QUENCH --- *)
        dwStatusWord := 16#00000040; (* Status: Micro-Arc Quench Active *)
        bArcSuppressionActive := TRUE;

        (* Execute fast reverse voltage bias pulse (25 us nominal simulated across scan cycle) *)
        tArcQuenchTimer(IN := TRUE, PT := T#2MS);

        IF tArcQuenchTimer.Q THEN
            tArcQuenchTimer(IN := FALSE);
            bArcSuppressionActive := FALSE;

            (* Check if plasma recovers gracefully *)
            IF (ABS(rCathodeVoltageVoted_V) > 260.0) AND (rCathodeCurrentVoted_A > 6.0) THEN
                iHardArcConsecutiveCount := 0;
                iState := 50; (* Resume Steady-State Deposition *)
            ELSE
                (* Quench failed to clear arc: Escalate to Hard Arc Suppression *)
                iState := 70;
            END_IF;
        END_IF;

    70: (* --- STATE 70: HARD-ARC SUPPRESSION & PLASMA RESTRIKE --- *)
        dwStatusWord := 16#00000080; (* Status: Hard-Arc Suppression Gating *)
        bArcSuppressionActive := TRUE;
        iHardArcConsecutiveCount := iHardArcConsecutiveCount + 1;
        tStateTimer(IN := TRUE, PT := T#50MS);

        IF iHardArcConsecutiveCount > 3 THEN
            (* Target damage prevention: Maximum allowable successive hard arcs exceeded *)
            dwAlarmWord := dwAlarmWord OR 16#00001000; (* Bit 12: Permanent Hard Arc Lockout *)
            bArcSuppressionActive := FALSE;
            iState := 80; (* Force Rampdown *)
        ELSIF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            bArcSuppressionActive := FALSE;
            iState := 40; (* Attempt Gentle Power Ramp Recovery *)
        END_IF;

    80: (* --- STATE 80: CONTROLLED GRACEFUL POWER RAMPDOWN --- *)
        dwStatusWord := 16#00000100; (* Status: Controlled Graceful Rampdown *)
        bArcSuppressionActive := FALSE;

        (* Controlled deceleration of target power to prevent thermal shock to ceramic bonded targets *)
        IF rPowerRampCurrent_kW > 0.5 THEN
            rPowerRampCurrent_kW := rPowerRampCurrent_kW - (rPowerRampRate_kW_s * 1.5 * rCycleTime_s);
        ELSE
            rPowerRampCurrent_kW := 0.0;
            bPlasmaActive := FALSE;
            IF dwAlarmWord <> 0 THEN
                iState := 99; (* Enter Lockout if rampdown was alarm-induced *)
            ELSE
                iState := 0;  (* Return to Normal Standby *)
            END_IF;
        END_IF;

    99: (* --- STATE 99: CRITICAL ALARM FAULT LOCKOUT --- *)
        dwStatusWord := 16#80000000; (* Status: Critical Trip Lockout *)
        bPlasmaActive := FALSE;
        bArcSuppressionActive := FALSE;
        bMatchingNetworkLocked := FALSE;
        bSystemHealthy := FALSE;
        rPowerRampCurrent_kW := 0.0;
        rCathodePowerActual_kW := 0.0;
        (* Maintain lockout until physical safety cleared and bResetFault pulsed *)
END_CASE;

